  'Configurar IA más tarde': 'Configure AI later',
  'Podrás explorar este vault sin IA. Las funciones que analizan, generan contenido o usan búsqueda semántica no estarán disponibles hasta que configures los modelos en Ajustes → Modelos IA.':
    'You can explore this vault without AI. Features that analyse, generate content, or use semantic search will remain unavailable until you configure models in Settings → AI Models.',
  'Explorar sin IA': 'Explore without AI',
  'Al crear la bóveda, el asistente te llevará a elegir su modelo de IA y su modelo de embeddings, con los modelos de tus proveedores ya cargados.': 'Once the vault is created, the wizard will take you to choose its AI model and its embedding model, with your providers’ models already loaded.',
  'En el siguiente paso elegirás el modelo de IA y el de embeddings. Nodus detecta tus claves y carga los modelos disponibles por ti.': 'In the next step you will choose the AI model and the embedding model. Nodus detects your keys and loads the available models for you.',
