  'Sin conectar': 'Not connected',
  'Borrar conexión con ChatGPT': 'Delete ChatGPT connection',
  'Nodus eliminará de este equipo el ID del túnel y la clave de ejecución guardada. Podrás configurarlos otra vez cuando quieras.':
    'Nodus will remove the tunnel ID and stored runtime key from this device. You can configure them again at any time.',
  'Borrar conexión': 'Delete connection',
  'Conectar Nodus': 'Connect Nodus',
