  'Ver detalle técnico': 'View technical details',
  'Cuando uses Nodus desde ChatGPT, OpenAI recibirá las consultas y los resultados que ChatGPT solicite. Las bóvedas permanecen en este equipo y el servidor local no se publica en Internet.':
    'When you use Nodus from ChatGPT, OpenAI receives the requests and results that ChatGPT asks for. Your vaults remain on this device and the local server is not published on the internet.',
  'Borrar conexión guardada': 'Delete stored connection',
  'Claude Desktop puede conectar directamente con el servidor local de Nodus mediante este puente stdio:':
    'Claude Desktop can connect directly to Nodus\'s local server through this stdio bridge:',
  'Copia esta configuración en Claude Desktop y reinicia la aplicación.': 'Copy this configuration into Claude Desktop and restart the app.',
  'Usa Streamable HTTP con la URL local y la cabecera bearer siguientes.': 'Use Streamable HTTP with the following local URL and bearer header.',
  'El ID debe empezar por tunnel_ y contener los 32 caracteres que muestra OpenAI.': 'The ID must start with tunnel_ and contain the 32 characters shown by OpenAI.',
  'Falta la clave de ejecución de OpenAI.': 'The OpenAI runtime key is missing.',
  'OpenAI todavía no ofrece el cliente de túnel para este sistema.': 'OpenAI does not yet provide the tunnel client for this system.',
  'No se pudo descargar el cliente oficial. Comprueba la conexión a Internet e inténtalo de nuevo.': 'The official client could not be downloaded. Check your internet connection and try again.',
  'La descarga no superó la comprobación de seguridad y no se ha ejecutado.': 'The download failed the security check and was not run.',
  'OpenAI rechazó la clave. Crea una clave de ejecución nueva y vuelve a pegarla.': 'OpenAI rejected the key. Create a new runtime key and paste it again.',
  'Tu cuenta necesita permisos Tunnels Read + Use en la organización de OpenAI.': 'Your account needs Tunnels Read + Use permissions in the OpenAI organization.',
  'OpenAI no encuentra ese túnel en la organización asociada a la clave.': 'OpenAI cannot find that tunnel in the organization associated with the key.',
  'No se puede alcanzar OpenAI. Revisa la conexión, el proxy o el cortafuegos.': 'OpenAI cannot be reached. Check your connection, proxy, or firewall.',
