  // ── Databases demo + tour ───────────────────────────────────────────────────
  'Demo de bases de datos': 'Databases demo',
  'Tres tablas de investigación con todos los tipos de columna, relaciones, registros, análisis, una conversación y notas de ejemplo. Incluye un tutorial guiado.':
    'Three research tables with every column type, relations, records, analysis, a conversation and sample notes. Includes a guided tutorial.',
  'Cargar demo de bases de datos': 'Load databases demo',
  'Cargar datos de ejemplo': 'Load sample data',
  'Tutorial de bases de datos': 'Databases tutorial',
  'La lista de bases de datos, la tabla con columnas tipadas, la edición de celdas y las secciones de análisis y chat.':
    'The database list, the table with typed columns, cell editing, and the analysis and chat sections.',
  'Se mostrará el tutorial de bases de datos.': 'The databases tutorial will be shown.',
  'Bienvenido al modo bases de datos': 'Welcome to databases mode',
  'Este es el modo bases de datos de Nodus: un gestor de tablas al estilo Notion, integrado en tu app. Te enseño en un minuto sus piezas con tres bases de datos de ejemplo ya cargadas. Puedes salir cuando quieras y volver a ver el tutorial desde Ajustes.':
    "This is Nodus's databases mode: a Notion-style table manager built into your app. In a minute I'll walk you through its parts using three sample databases already loaded. You can leave any time and replay the tutorial from Settings.",
  'Tus bases de datos': 'Your databases',
  'En la barra lateral aparecen todas tus bases de datos. Cada una tiene un identificador único autogenerado. Pulsa una para abrirla, o el botón + para crear una nueva. Aquí abajo están también las secciones de Análisis y Chat.':
    'All your databases appear in the sidebar. Each has an auto-generated unique id. Click one to open it, or the + button to create a new one. The Analysis and Chat sections are below.',
  'La tabla': 'The table',
  'Cada base de datos es una tabla de columnas tipadas: título, texto, número, fecha, hora, selección, selección múltiple y casilla. Arriba verás el número total de entradas y el porcentaje que suponen del total de todas tus bases de datos.':
    'Each database is a table of typed columns: title, text, number, date, time, select, multi-select and checkbox. At the top you see the total number of entries and their percentage of all your databases.',
  'Edita directamente': 'Edit in place',
  'Haz clic en cualquier celda para editarla al momento. Las columnas de selección muestran opciones con color que puedes añadir sobre la marcha; las casillas se marcan con un clic. Pasa el ratón por una fila para borrarla.':
    'Click any cell to edit it instantly. Select columns show colour-coded options you can add on the fly; checkboxes toggle with a click. Hover a row to delete it.',
  'Columnas a tu medida': 'Columns your way',
  'Pulsa la cabecera de una columna para renombrarla, cambiar su tipo o gestionar sus opciones, y usa el botón + del final de la cabecera para añadir nuevas columnas. Con «Nueva fila» añades registros.':
    'Click a column header to rename it, change its type or manage its options, and use the + at the end of the header to add new columns. "New row" adds records.',
  'Análisis (próximamente)': 'Analysis (coming soon)',
  'Aquí podrás elegir una base de datos y obtener estadísticas automáticas más un informe con IA, con gráficos y el cálculo a la vista para que sea reproducible. Llega en una próxima fase.':
    'Here you will pick a database and get automatic statistics plus an AI report, with charts and the calculation on show so it stays reproducible. Arriving in a later phase.',
  'Chat de datos (próximamente)': 'Data chat (coming soon)',
  'Un chat adaptado para conversar con una o varias de tus bases de datos, capaz de generar gráficos y consultas reproducibles. También llega en una próxima fase.':
    'A chat tailored to converse with one or several of your databases, able to generate charts and reproducible queries. Also arriving in a later phase.',
  'Listo para tus datos': 'Ready for your data',
  'Esto es una demostración con datos de ejemplo. Cuando quieras empezar con los tuyos, crea una base de datos desde la barra lateral y añade tus columnas. Pronto podrás además importar CSV y subir archivos en masa.':
    'This is a demo with sample data. When you want to start with your own, create a database from the sidebar and add your columns. Soon you will also be able to import CSV and bulk-upload files.',

