  'Copiar clave': 'Copy key',
  'Guarda el kit fuera de este dispositivo. Podrás restaurar con la contraseña o con la clave de recuperación.': 'Store the kit away from this device. You can restore with the password or the recovery key.',
  'Continuar a Nodus': 'Continue to Nodus',
  'PROTECCIÓN DE DATOS': 'DATA PROTECTION',
  'Hemos detectado una instalación anterior': 'We detected an existing installation',
  'Elige dónde proteger Nodus': 'Choose where to protect Nodus',
  'Tus bóvedas actuales no se moverán ni se modificarán. Crearemos una primera copia cifrada y verificada antes de activar la recuperación.': 'Your current vaults will not be moved or modified. We will create and verify a first encrypted snapshot before enabling recovery.',
  'Configura una carpeta segura antes de empezar. Tus bóvedas seguirán trabajando localmente y Nodus guardará aquí copias recuperables.': 'Configure a safe folder before you start. Your vaults keep working locally and Nodus stores recoverable snapshots here.',
  'La base de datos activa nunca se abre directamente desde Google Drive o Dropbox: así evitamos conflictos y corrupción.': 'The live database is never opened directly from Google Drive or Dropbox, preventing conflicts and corruption.',
  'Migrar y proteger este equipo': 'Protect this computer',
  'Crear carpeta segura': 'Create safe folder',
  'Recuperar otro equipo': 'Restore another computer',
  '1. Selecciona una carpeta vacía': '1. Select an empty folder',
  '1. Selecciona la carpeta existente': '1. Select the existing folder',
  'Puede ser una carpeta local o una carpeta sincronizada por Google Drive, Dropbox, iCloud u otro servicio. Debe estar vacía.': 'It may be local or synchronized by Google Drive, Dropbox, iCloud or another service. It must be empty.',
  'Busca la carpeta que contiene nodus-recovery.json y sus copias.': 'Choose the folder containing nodus-recovery.json and its snapshots.',
  '2. Todo Nodus quedará protegido': '2. All of Nodus will be protected',
  'Sin selecciones ni exclusiones: todas las bóvedas, documentos, preferencias, historiales, medios y claves API se incluirán automáticamente.': 'No selections or exclusions: every vault, document, preference, history, media file and API key is included automatically.',
  '2. Elige una copia': '2. Choose a snapshot',
  'La más reciente aparece seleccionada. Puedes recuperar una versión anterior.': 'The newest snapshot is selected. You may restore an older version.',
  '3. Crea una contraseña maestra': '3. Create a master password',
  '3. Introduce una credencial': '3. Enter a credential',
  'Protege tus copias junto con una clave de recuperación independiente. Debe tener al menos 8 caracteres.': 'It protects your snapshots alongside an independent recovery key. Use at least 8 characters.',
  'Puedes usar la contraseña maestra o la clave de recuperación de tu kit.': 'Use either the master password or the recovery key from your kit.',
