  "Quedan {n} criterios sin marcar; la nota se calcula solo sobre los evaluados.": "{n} criteria are still unmarked; the mark is computed over the assessed ones only.",
  "Todos los criterios están evaluados.": "Every criterion has been assessed.",
  "hasta {n} puntos": "up to {n} points",
