  'Semilla visual': 'Visual seed',
  'Un texto corto y estable que se añade a TODAS las imágenes que generes de este personaje. Es lo que consigue que se parezca a sí mismo de una imagen a otra, así que conviene cambiarlo lo menos posible.': 'A short, stable text added to EVERY image you generate of this character. It is what makes them resemble themselves from one image to the next, so change it as little as possible.',
