  'Retrato con IA': 'AI portrait',
  'Se usa la apariencia y la semilla visual de la ficha, así que el personaje mantiene el mismo aspecto entre imágenes.': 'It uses the sheet’s appearance and visual seed, so the character keeps the same look across images.',
