  'Tu mundo': 'Your world',
  'Construye un mundo de ficción pieza a pieza. Empieza por los personajes: sus nombres y alias, los hechos de su vida, sus vínculos y su descripción, con retratos y biografías que puedes generar cuando te sirvan.': 'Build a fictional world piece by piece. Start with the characters: their names and aliases, the events of their lives, their bonds and their description, with portraits and biographies you can generate whenever they help.',
