  'Escribe el tema o la lección que quieres preparar. El informe diseñará objetivos, secuencia, actividades y evaluación usando tus materiales.': 'Enter the topic or lesson you want to prepare. The report will design objectives, sequence, activities, and assessment from your materials.',
