  'Generará explicaciones, definiciones, ejemplos, síntesis y autoevaluación dirigidos al alumnado.': 'It will generate student-facing explanations, definitions, examples, summaries, and self-assessment.',
  'En «Crear», Unidades didácticas ya permite generar una planificación para el docente o apuntes para el alumnado a partir de tus materiales. Las demás secciones punteadas siguen abiertas a tus sugerencias. Puedes repetir este tutorial desde Ajustes.': 'Under “Create”, Teaching units can now generate a teacher plan or student notes from your materials. The remaining dotted sections are still open to your suggestions. You can replay this tutorial from Settings.',
