  'Los artículos son para lo que no es un personaje, un lugar ni una facción: la magia, una religión, una lengua, una criatura, un objeto. Todo lo demás ya está en la enciclopedia por sí solo.': 'Articles are for whatever is not a character, a place or a faction: magic, a religion, a language, a creature, an object. Everything else is already in the encyclopedia on its own.',
