  'En la enciclopedia': 'In the encyclopedia',
  '{count} sin desarrollar': '{count} undeveloped',
  'Construye un mundo de ficción pieza a pieza: personajes, lugares, facciones, culturas, escenas y mapas. La enciclopedia los reúne todos en un solo índice y te deja escribir el resto del mundo —la magia, una religión, una lengua— enlazándolo con [[dobles corchetes]].': 'Build a fictional world piece by piece: characters, places, factions, cultures, scenes and maps. The encyclopedia gathers them all into one index and lets you write the rest of the world — magic, a religion, a language — linking it with [[double brackets]].',
