  // ── Preguntas abiertas (worldbuilding) ──────────────────────────────────
  "Alt+Q": "Alt+Q",
  "Aparcada": "Parked",
  "Aparcada. Si venía de un hueco en tu prosa, seguirá aparcada aunque reescribas la frase.": "Parked. If it came from a hole in your prose, it stays parked even if you rewrite the sentence.",
  "Aparcarla: no me lo vuelvas a enseñar": "Park it: stop showing me this",
  "Aplicada. El texto ha cambiado desde entonces, así que ya no se puede deshacer sola.": "Applied. The text has changed since then, so it can no longer undo itself.",
  "Buscar entre las decisiones…": "Search the decisions…",
