  "Lo que todavía no has decidido de tu mundo. Desde una ficha se captura sola, con su sitio ya puesto.": "What you have not decided about your world yet. From a sheet it captures itself, with its place already set.",
  "Me bloquea": "It blocks me",
  "Ninguna decisión coincide con el filtro.": "No decision matches the filter.",
  "No puedes escribir «{scene}» sin decidirlo (escena {order} del relato).": "You cannot write “{scene}” without deciding it (scene {order} of the story).",
  "No puedo seguir sin esto": "I cannot go on without this",
  "No queda nada por decidir: ni preguntas tuyas, ni huecos (???, TBD, XXX, […]) en tu prosa.": "Nothing left to decide: no questions of your own, and no holes (???, TBD, XXX, […]) in your prose.",
  "Otra respuesta posible…": "Another possible answer…",
  "Pregunta abierta guardada sobre {title}.": "Open question saved about {title}.",
