  "Todavía no has decidido nada aquí.": "You have not decided anything here yet.",
  "Todavía no hay nada más en el mundo que dependa de esto.": "Nothing else in the world depends on this yet.",
  "Un hueco en tu prosa": "A hole in your prose",
