  "¿La magia deja marca visible?": "Does magic leave a visible mark?",
  "El modelo no ha devuelto ninguna respuesta que pueda usar.": "The model returned no answer I can use.",
  "Escribe primero qué es lo que no has decidido: «???» a secas no da para responder.": "Write down what you have not decided first: a bare “???” gives nothing to answer.",
  "Proponer respuestas": "Propose answers",
  "Solo el enunciado. El precio y los límites los escribes tú: cada uno responde a una pregunta distinta.": "The statement only. The price and the limits are yours to write: each one answers a different question.",
  "Todavía no hay de dónde escribirla: dime sobre qué rige, empieza una línea o márcala en una escena.": "There is nothing to write it from yet: tell me what it governs, start a line, or mark it in a scene.",
  "Ha mirado": "It looked at",
  "No escribe nada en tu mundo: lo que te proponga, lo copias tú o lo conviertes en pregunta abierta.": "It writes nothing into your world: whatever it suggests, you copy it yourself or turn it into an open question.",
  "No he encontrado nada de tu mundo en esa pregunta. Nombra un personaje, un lugar, una escena o una ley y vuelvo a mirar.": "I found nothing of your world in that question. Name a character, a place, a scene or a law and I will look again.",
  "Nodus calcula y el modelo redacta: responde con lo que hay en tus fichas, y cita.": "Nodus calculates and the model writes: it answers from what your sheets say, and it cites.",
  "Pregúntale a tu mundo. Nombra en la pregunta lo que quieras que mire.": "Ask your world. Name in the question whatever you want it to look at.",
  "Seguir con esto": "Stay on this",
