  "¿Podía hacerlo, ahí y entonces?": "Could they do it, there and then?",
  "¿Quién sabía el secreto en ese momento?": "Who knew the secret at that point?",
  "¿Qué leyes alcanzan a mi protagonista?": "Which laws reach my protagonist?",
