  "Limpieza automática de copias antiguas": "Automatic cleanup of old backups",
  "Usa el mismo día y hora que las copias automáticas. Si Nodus estaba cerrado, la limpieza pendiente se ejecuta al volver a abrirlo.": "Uses the same day and time as automatic backups. If Nodus was closed, overdue cleanup runs when you reopen it.",
  "Configura primero la carpeta de Recuperación y la contraseña maestra para poder verificar una copia superviviente.": "Set up the Recovery folder and master password first so a surviving backup can be verified.",
  "Configurar Recuperación": "Set up Recovery",
  "Mover copias con más de": "Move backups older than",
  "días": "days",
  "semanas": "weeks",
  "meses": "months",
  "años": "years",
  "{count} copia(s), {size}, supera(n) ahora la antigüedad configurada.": "{count} backup(s), {size}, currently exceed the configured age.",
  "Siempre se conservan al menos las tres copias normales más recientes. Las copias de otros equipos y los snapshots pre-update nunca entran en esta limpieza.": "At least the three most recent regular backups are always kept. Backups from other computers and pre-update snapshots are never included in this cleanup.",
  "{count} copia(s) permanece(n) en la papelera de seguridad.": "{count} backup(s) remain in safety trash.",
  "{count} copia(s) ({size}) ya cumplió/cumplieron siete días en la papelera de seguridad y se eliminará(n) definitivamente en esta limpieza.": "{count} backup(s) ({size}) have already spent seven days in safety trash and will be permanently deleted by this cleanup.",
  "Las copias seleccionadas se mueven primero a una papelera privada dentro de la carpeta de Recuperación. Solo se eliminan definitivamente después de siete días y tras verificar otra copia válida.": "Selected backups first move to private safety trash inside the Recovery folder. They are permanently deleted only after seven days and after another valid backup is verified.",
  "Al activar esta opción, el límite de antigüedad sustituye la rotación compacta anterior para las nuevas copias de este equipo.": "When enabled, the age limit replaces the previous compact rotation for new backups from this computer.",
  "Para cambiar la antigüedad, desactiva primero la limpieza y vuelve a activarla para confirmar el nuevo alcance.": "To change the age limit, turn cleanup off first and enable it again to confirm the new scope.",
  "Limpiando…": "Cleaning…",
  "Revisar y limpiar ahora": "Review and clean now",
  "Última limpieza": "Last cleanup",
  "¿Activar la limpieza automática?": "Enable automatic cleanup?",
  "Esta opción puede retirar copias antiguas automáticamente. Comprueba con atención la antigüedad seleccionada antes de continuar.": "This option can automatically remove old backups. Carefully check the selected age before continuing.",
  "Con la configuración actual, {count} copia(s) ({size}) pasaría(n) a la papelera de seguridad.": "With the current settings, {count} backup(s) ({size}) would move to safety trash.",
  "Las tres copias normales más recientes, las copias de otros equipos y los snapshots pre-update quedan protegidos.": "The three most recent regular backups, backups from other computers, and pre-update snapshots remain protected.",
  "Ninguna copia que se mueva en esta ejecución se eliminará definitivamente: permanecerá siete días en la papelera de seguridad.": "No backup moved during this run will be permanently deleted: it will remain in safety trash for seven days.",
  "Activar y ejecutar limpieza": "Enable and run cleanup",
  "¿Revisar y limpiar copias antiguas?": "Review and clean old backups?",
  "{count} copia(s) ({size}) cumple(n) ahora la regla de antigüedad.": "{count} backup(s) ({size}) currently match the age rule.",
  "Nodus volverá a calcular y verificar todo justo antes de mover archivos. Si algo no coincide, la operación se cancela sin borrar datos.": "Nodus will recalculate and verify everything immediately before moving files. If anything does not match, the operation is cancelled without deleting data.",
  "Las copias pasarán primero a la papelera de seguridad durante siete días.": "Backups will first move to safety trash for seven days.",
  "Ejecutar limpieza segura": "Run safe cleanup",
  "{count} copia(s) se movió/movieron a la papelera de seguridad.": "{count} backup(s) moved to safety trash.",
  "{count} copia(s) se eliminó/eliminaron definitivamente tras siete días.": "{count} backup(s) were permanently deleted after seven days.",
  "No hay copias que superen la antigüedad configurada.": "No backups exceed the configured age.",
  "La vista previa ya no está disponible. Revísala de nuevo antes de limpiar.": "The preview is no longer available. Review it again before cleaning.",
  "La carpeta de copias cambió desde la vista previa. No se ha modificado nada; revisa el alcance y vuelve a confirmar.": "The backup folder changed after the preview. Nothing was modified; review the scope and confirm again.",
  "La confirmación de limpieza no es válida. Revisa de nuevo el alcance.": "The cleanup confirmation is invalid. Review the scope again.",
  "Nodus Connector para Chrome": "Nodus Connector for Chrome",
  "Guarda la página o documento abierto en la Biblioteca de Nodus con metadatos, archivos, colección y etiquetas. Solo lee la pestaña cuando pulsas el icono.": "Save the open page or document to the Nodus Library with metadata, files, a collection, and tags. It only reads the tab when you click the icon.",
