  "Esta página dejó de responder": "This page stopped responding",
  "Ojo: si entras en tu navegador, la sesión se queda allí. Seguirás sin haber iniciado sesión en {host} dentro de Nodus, porque las cookies no se comparten entre navegadores.": "Note: if you sign in in your browser, the session stays there. You will still be signed out of {host} inside Nodus, because cookies are not shared between browsers.",
  "Ojo: si entras en tu navegador, la sesión se queda allí. Seguirás sin haber iniciado sesión en Google dentro de Nodus, porque las cookies no se comparten entre navegadores.": "Note: if you sign in in your browser, the session stays there. You will still be signed out of Google inside Nodus, because cookies are not shared between browsers.",
  "Si {host} admite entrar con contraseña o con un enlace por correo, esa vía sí funciona aquí dentro, y Nodus recordará la sesión.": "If {host} accepts a password or an email link, that route does work in here, and Nodus will remember the session.",
  "Volver e intentar con contraseña": "Go back and try a password",
  "Usar {host} en mi navegador": "Use {host} in my browser",
  "Para que Nodus lea tu Gmail o tu Drive haría falta otra cosa: conectar la cuenta desde Ajustes, que es la vía que Google sí admite para aplicaciones de escritorio. Todavía no está disponible.": "For Nodus to read your Gmail or Drive, something else would be needed: connecting the account from Settings, which is the route Google does allow for desktop applications. Not available yet.",
  "No es un fallo de Nodus: Google rechaza el inicio de sesión desde cualquier navegador incrustado en otra aplicación.": "This is not a Nodus fault: Google refuses sign-in from any browser embedded in another application.",
  "Google no permite iniciar sesión desde un navegador integrado": "Google does not allow signing in from an embedded browser",
  "Abrir en tu navegador": "Open in your browser",
