  "Borrar las cookies cerrará tu sesión en los sitios donde la tengas iniciada.": "Deleting cookies will sign you out of the sites where you are signed in.",
  "También se cerrarán todas las pestañas abiertas del navegador.": "All open browser tabs will be closed too.",
  "Chromium borra las cookies por dominio registrable: al borrar las de un subdominio se borran también las del dominio principal y sus demás subdominios.": "Chromium clears cookies by registrable domain: clearing a subdomain's cookies also clears the main domain's and those of its other subdomains.",
  "Nodus puede medir la caché y el tamaño total del perfil. Chromium no informa del tamaño de cada categoría de almacenamiento por separado, así que las demás se muestran por número de sitios afectados.": "Nodus can measure the cache and the total profile size. Chromium does not report the size of each storage category separately, so the rest are shown by the number of sites affected.",
  "Nodus Browser conserva cookies y almacenamiento de sitio para que sigas con la sesión iniciada donde corresponda. Nodus no guarda usuarios ni contraseñas, y no incluye gestor de contraseñas.": "Nodus Browser keeps cookies and site storage so you stay signed in where appropriate. Nodus stores no usernames and no passwords, and includes no password manager.",
